import { Component, inject, computed, effect, ViewChild, ElementRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FinancialService } from '../../core/services/financial.service';
import { FinancialTableComponent } from '../../shared/components/financial-table/financial-table.component';
import { KpiCardComponent } from '../../shared/components/kpi-card/kpi-card.component';
import { Chart, registerables } from 'chart.js';

Chart.register(...registerables);

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, FinancialTableComponent, KpiCardComponent],
  templateUrl: './dashboard.component.html'
})
export class DashboardComponent {
  financialService = inject(FinancialService);
  Object = Object;

  @ViewChild('chartAtivo') chartAtivo!: ElementRef;
  @ViewChild('chartPassivo') chartPassivo!: ElementRef;
  @ViewChild('chartEvolucao') chartEvolucao!: ElementRef;
  @ViewChild('chartDre') chartDre!: ElementRef;

  private charts: Chart[] = [];
  recomendacoesManuais: string[] = [];

  constructor() {
    effect(() => {
      const data = this.financialService.dashboardData();
      if (data && data.graficos) {
        setTimeout(() => this.initCharts(data), 100);
      }
    });
  }

  // ETAPA 8: Lógica de Recomendações Estratégicas
  todasRecomendacoes = computed(() => {
    const data = this.financialService.dashboardData();
    if (!data) return [];
    
    const ind = data.indices;
    const automaticas: any[] = [];

    // Gatilhos de IA baseados nos dados reais da ITASUL
    if (ind['liq_corrente'] < 1.0) {
      automaticas.push({
        titulo: "Reestruturação de Passivo",
        texto: `A liquidez de ${ind['liq_corrente']} exige renegociação imediata das dívidas de curto prazo para evitar insolvência.`,
        urgencia: "ALTA"
      });
    }

    if (ind['endiv_geral'] > 70) {
      automaticas.push({
        titulo: "Equilíbrio de Capital",
        texto: `O endividamento de ${ind['endiv_geral']}% está crítico. Recomendado aporte de capital ou venda de ativos ociosos.`,
        urgencia: "CRÍTICA"
      });
    }

    const melhorRegime = data.comparativo_tributario?.find((r: any) => r.economica);
    if (melhorRegime && melhorRegime.nome === 'Lucro Real') {
      automaticas.push({
        titulo: "Migração Tributária",
        texto: `Migrar para o Lucro Real pode gerar uma economia anual estimada de ${melhorRegime.valor.toLocaleString('pt-BR', {style: 'currency', currency: 'BRL'})}.`,
        urgencia: "ESTRATÉGICA"
      });
    }

    // Une com as notas que você escrever manualmente no botão
    const manuais = this.recomendacoesManuais.map(txt => ({
      titulo: "Nota do Especialista",
      texto: txt,
      urgencia: "PERSONALIZADA"
    }));

    return [...automaticas, ...manuais];
  });

  adicionarRecomendacao() {
    const rec = prompt("Digite sua recomendação estratégica para o cliente:");
    if (rec) {
      this.recomendacoesManuais = [...this.recomendacoesManuais, rec];
    }
  }

  private initCharts(data: any) {
    this.charts.forEach(c => c.destroy());
    this.charts = [];
    const commonOptions = { responsive: true, maintainAspectRatio: false };

    this.charts.push(new Chart(this.chartAtivo.nativeElement, {
      type: 'doughnut',
      data: {
        labels: data.graficos.composicao_ativo.map((i: any) => i.name),
        datasets: [{
          data: data.graficos.composicao_ativo.map((i: any) => i.value),
          backgroundColor: ['#10b981', '#e2e8f0']
        }]
      },
      options: { ...commonOptions, cutout: '60%', plugins: { legend: { position: 'bottom' } } }
    }));

    this.charts.push(new Chart(this.chartPassivo.nativeElement, {
      type: 'doughnut',
      data: {
        labels: data.graficos.composicao_passivo.map((i: any) => i.name),
        datasets: [{
          data: data.graficos.composicao_passivo.map((i: any) => i.value),
          backgroundColor: ['#f43f5e', '#94a3b8', '#10b981']
        }]
      },
      options: { ...commonOptions, cutout: '60%', plugins: { legend: { position: 'bottom' } } }
    }));

    this.charts.push(new Chart(this.chartEvolucao.nativeElement, {
      type: 'line',
      data: {
        labels: data.graficos.evolucao_patrimonial.categorias,
        datasets: [
          { label: 'Anterior', data: data.graficos.evolucao_patrimonial.anterior, borderColor: '#94a3b8', tension: 0.4 },
          { label: 'Atual', data: data.graficos.evolucao_patrimonial.atual, borderColor: '#10b981', tension: 0.4 }
        ]
      },
      options: commonOptions
    }));

    this.charts.push(new Chart(this.chartDre.nativeElement, {
      type: 'bar',
      data: {
        labels: data.graficos.dre.map((i: any) => i.name),
        datasets: [{ label: 'Valor', data: data.graficos.dre.map((i: any) => i.valor), backgroundColor: '#10b981' }]
      },
      options: commonOptions
    }));
  }

  // ... (métodos de classes e notas permanecem iguais)
  pontosPositivos = computed(() => {
    const data = this.financialService.dashboardData();
    if (!data) return [];
    const items: string[] = [];
    if (data.indices['roa'] > 15) items.push('✅ Excelente retorno sobre ativos (ROA).'); 
    return items;
  });

  pontosAtencao = computed(() => {
    const data = this.financialService.dashboardData();
    if (!data) return [];
    const items: string[] = [];
    if (data.indices['liq_corrente'] < 1.0) items.push('⚠️ Risco imediato de insolvência.'); 
    return items;
  });

  getIndicatorClass(key: string, value: number) { /* código anterior */ return 'text-slate-600'; }
  getIndicatorNote(key: string, value: number) { /* código anterior */ return ''; }
  getAnosProcessados(anosObj: any) { return anosObj ? Object.keys(anosObj).sort().join(' VS ') : '...'; }
  onFileSelected(event: any) {
    const files = event.target.files;
    if (files.length) this.financialService.uploadFiles(Array.from(files)).subscribe();
  }
  print() { window.print(); } 
}
